def get_formatted_profile():
    """Returns the candidate profile in a formatted string for the AI agent"""
    profile_text = f"CANDIDATE PROFILE - {CANDIDATE_NAME}\n\n"
    
    for key, value in CANDIDATE_PROFILE.items():
        # Convert key to readable format
        readable_key = key.replace('_', ' ').title()
        profile_text += f"{readable_key}: {value.strip()}\n\n"
    
    return profile_text 